(function(){
'use strict';
function evaluate(x){if(!x||typeof x.amount!=='number'||!Number.isFinite(x.amount)||x.amount<1||x.amount>10000||typeof x.network!=='number'||!Number.isFinite(x.network)||x.network<0||x.network>100||['merchant','device','wallet'].some(k=>typeof x[k]!=='boolean'))throw new Error('Enter an amount from $1 to $10,000, risk from 0 to 100, and valid signal choices.');let score=Math.min(100,x.network+(x.merchant?0:15)+(x.device?0:20)+(x.amount>=500?15:0));return {score,action:score<35?'approve':score<70?'verify':'block',wallet:x.wallet,reasons:[`Network signal: ${x.network}`,x.merchant?'Familiar merchant: +0':'Unfamiliar merchant: +15',x.device?'Recognized device: +0':'New device: +20',x.amount>=500?'Amount ≥ $500: +15':'Amount below $500: +0']};}
function confirm(r,yes){if(r.action!=='verify'||typeof yes!=='boolean')throw new Error('Verification requires a pending verify decision and a yes/no answer.');return {...r,action:yes?'approve':'block',confirmed:yes};}
function recover(r){if(r.action!=='block')throw new Error('Recovery requires a blocked transaction.');return r.wallet?'Demo digital access activated':'Assisted recovery required';}
function tests(){let logs=[];function check(name,fn){try{if(!fn())throw Error('Unexpected result');logs.push('PASS · '+name);}catch(e){logs.push('FAIL · '+name+': '+e.message);}}let base={amount:45,network:10,merchant:true,device:true,wallet:true};check('Routine approval',()=>evaluate(base).action==='approve');let unusual=evaluate({...base,amount:800,network:25,merchant:false});check('Unusual purchase → verify',()=>unusual.score===55&&unusual.action==='verify');check('Confirmed legitimate purchase → approve',()=>confirm(unusual,true).action==='approve');check('Rejected purchase → block',()=>confirm(unusual,false).action==='block');let high=evaluate({...base,amount:1200,network:60,merchant:false,device:false});check('High risk → block; score capped at 100',()=>high.action==='block'&&high.score===100);check('Supported wallet → simulated activation',()=>recover(high)==='Demo digital access activated');check('Unsupported wallet → assisted recovery',()=>recover({...high,wallet:false})==='Assisted recovery required');[34,35,69,70].forEach(n=>check('Threshold '+n,()=>evaluate({...base,network:n}).action===(n<35?'approve':n<70?'verify':'block')));[-1,101,NaN].forEach(n=>check('Reject invalid risk '+n,()=>{try{evaluate({...base,network:n});return false;}catch{return true;}}));check('Reject invalid amount',()=>{try{evaluate({...base,amount:0});return false;}catch{return true;}});check('Reject nonboolean signals',()=>{try{evaluate({...base,wallet:'yes'});return false;}catch{return true;}});check('Prevent recovery before block',()=>{try{recover(unusual);return false;}catch{return true;}});check('Prevent repeated verification',()=>{try{confirm(high,true);return false;}catch{return true;}});return logs;}
if(typeof module!=='undefined')module.exports={evaluate,confirm,recover,tests};
if(typeof document==='undefined')return;
const result=document.getElementById('result');let state;
function render(r){state=r;result.replaceChildren();const badge=document.createElement('span');badge.className='badge';badge.textContent='Synthetic decision · Policy v1';result.append(badge);const h=document.createElement('h2');h.className='status';h.textContent={approve:'Purchase approved',verify:'Was this you?',block:'Purchase blocked'}[r.action];result.append(h);let note=document.createElement('p');note.textContent=`Illustrative risk score: ${r.score}/100. `+({approve:'The demo purchase can proceed.',verify:'Confirm whether you recognize this purchase.',block:'The demo purchase is stopped. Your next step is recovery.'}[r.action]);result.append(note);let reasons=document.createElement('p');reasons.textContent=r.reasons.join(' · ');result.append(reasons);if(r.action==='verify'){[['Yes, this was me',true],['No, not me',false]].forEach(([text,yes])=>{const b=document.createElement('button');b.textContent=text;b.onclick=()=>render(confirm(state,yes));result.append(b);});}if(r.action==='block'){const b=document.createElement('button');b.textContent=r.wallet?'Activate demo digital access':'Show assisted recovery';b.onclick=()=>{b.disabled=true;const p=document.createElement('p');p.textContent=recover(state)+(state.wallet?'. Synthetic wallet credential DEMO •••• 4821 is ready for the demonstration. No real card was issued.':'. No compatible wallet is selected. In a real service, contact the bank through its authenticated app for available recovery options.');result.append(p);};result.append(b);}}
const form=document.getElementById('transaction');if(form){const el=id=>document.getElementById(id);form.onsubmit=e=>{e.preventDefault();try{render(evaluate({amount:Number(el('amount').value),network:Number(el('network').value),merchant:el('merchant').checked,device:el('device').checked,wallet:el('wallet').checked}));}catch(err){result.textContent=err.message;}};el('scenario').onchange=()=>{const s={routine:[45,10,true,true],unusual:[800,25,false,true],fraud:[1200,60,false,false]}[el('scenario').value];['amount','network'].forEach((k,i)=>el(k).value=s[i]);el('merchant').checked=s[2];el('device').checked=s[3];state=null;result.innerHTML='<h2>Scenario ready</h2><p>Evaluate the updated transaction to start a new workflow.</p>';};if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'evaluate_demo_transaction',description:'Evaluate synthetic transaction signals and display the fraud decision. Does not authorize a real transaction.',inputSchema:{type:'object',properties:{amount:{type:'number',minimum:1,maximum:10000},network:{type:'number',minimum:0,maximum:100},merchant:{type:'boolean'},device:{type:'boolean'},wallet:{type:'boolean'}},required:['amount','network','merchant','device','wallet'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const r=evaluate(input);render(r);return r;}})).catch(()=>{});}catch{}}}
const run=document.getElementById('run-tests');if(run)run.onclick=()=>{let t=tests();document.getElementById('test-output').textContent=t.join('\n')+'\n'+t.filter(s=>s.startsWith('PASS')).length+'/'+t.length+' checks passed.';};
})();
